from typing import List
import heapq

class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        heap = []
        for num in nums:
            heapq.heappush(heap, num)
            # Remove smaller elements so only k largest remain.
            if len(heap) > k:
                heapq.heappop(heap)
        return heap[0]

